# ===================== GEO UTILS =====================

def _haversine(lat1, lon1, lat2, lon2):
    R = 6371.0
    phi1, phi2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlambda = math.radians(lon2 - lon1)

    a = (
        math.sin(dphi / 2) ** 2 +
        math.cos(phi1) * math.cos(phi2) * math.sin(dlambda / 2) ** 2
    )
    return 2 * R * math.atan2(math.sqrt(a), math.sqrt(1 - a))


# ===================== TIME HELPERS =====================

def _is_night_time(ts: datetime):
    hour = ts.hour
    return hour >= 21 or hour < 5


def _zone_multiplier(zone):
    if zone == "RED":
        return 1.5
    elif zone == "YELLOW":
        return 1.35
    return 1.2


def _dominant_zone(areas):
    if any(a["crime_zone"] == "RED" for a in areas):
        return "RED"
    if any(a["crime_zone"] == "YELLOW" for a in areas):
        return "YELLOW"
    return "GREEN"


# ===================== PUBLIC API =====================

def get_threat_score(lat: float, lon: float, ts: datetime) -> float:
    """
    Inputs:
        lat (float)
        lon (float)
        ts  (datetime)

    Output:
        threat_score (float 0–100)
    """

    hit_areas = []

    # ---- AREA MATCH ----
    for area in SEED_AREAS:
        if _haversine(lat, lon, area["lat"], area["lon"]) <= area["radius_km"]:
            hit_areas.append(area)

    if hit_areas:
        avg_crime_weight = sum(a["crime_weight"] for a in hit_areas) / len(hit_areas)
        zone = _dominant_zone(hit_areas)
    else:
        avg_crime_weight = 2.5
        zone = "GREEN"

    threat = avg_crime_weight * 10

    # ---- NIGHT MULTIPLIER ----
    if _is_night_time(ts):
        threat *= _zone_multiplier(zone)

    # ---- POLICE REDUCTION ----
    max_police_reduction = 0.0
    for ps in SEED_POLICE_STATIONS:
        d = _haversine(lat, lon, ps["lat"], ps["lon"])
        if d <= ps["radius_km"]:
            reduction = 25 * (1 - d / ps["radius_km"])
            max_police_reduction = max(max_police_reduction, reduction)

    # ---- HOSPITAL BUFFER ----
    hospital_reduction = 0.0
    for h in SEED_HOSPITALS:
        if _haversine(lat, lon, h["lat"], h["lon"]) <= h["radius_km"]:
            hospital_reduction = 5
            break

    threat = threat - max_police_reduction - hospital_reduction

    # Clamp
    threat = max(0.0, min(100.0, threat))

    return round(threat, 2)
